  console.log("3. Clear temporary files using Disk Cleanup.");
  console.log("4. Run Windows Update to install the latest updates.");
  console.log("5. Check your hard drive for errors using 'Check Disk'.");
  console.log("6. Disable unnecessary startup programs via Task Manager.");
  console.log("7. Consider upgrading hardware (e.g., RAM, SSD) if needed.");
  console.log("8. Monitor system performance using Task Manager or Resource Monitor.");
}

// Main function
