Here's a complete Python implementation of a **Binary Search Tree (BST)** that supports **insertion**, **searching**, and **deletion** (including the case where a node has two children using the **inorder successor** approach).

---

### ✅ Features:
- Handles all types of deletions.
- Outputs `YES` or `NO` for each `search` operation.

---

### ✅ Python Code:

```python
class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = TreeNode(key)
        else:
            self._insert_recursive(self.root, key)

    def _insert_recursive(self, node, key):
        if key < node.key:
            if node.left is None:
                node.left = TreeNode(key)
            else:
                self._insert_recursive(node.left, key)
        else:
            if node.right is None:
                node.right = TreeNode(key)
            else:
                self._insert_recursive(node.right, key)

    def search(self, key):
        return self._search_recursive(self.root, key)

    def _search_recursive(self, node, key):
        if node is None:
            return False
        if node.key == key:
            return True
        elif key < node.key:
            return self._search_recursive(node.left, key)
        else:
            return self._search_recursive(node.right, key)

    def delete(self, key):
        self.root = self._delete_recursive(self.root, key)

    def _delete_recursive(self, root, key):
        if root is None:
            return root

        if key < root.key:
            root.left = self._delete_recursive(root.left, key)
        elif key > root.key:
            root.right = self._delete_recursive(root.right, key)
        else:
            # Node with only one child or no child
            if root.left is None:
                return root.right
            elif root.right is None:
                return root.left

            # Node with two children: Get the inorder successor
            root.key = self._min_value_node(root.right).key

            # Delete the inorder successor
            root.right = self._delete_recursive(root.right, root.key)

        return root

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current


def main():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n = int(data[0])
    bst = BinarySearchTree()

    for line in data[1:n+1]:
        parts = line.split()
        if parts[0] == 'insert':
            x = int(parts[1])
