import json

def sort_dict_recursive(d):
    result = {}
    for key, value in d.items():
        result[key] = value
        if isinstance(value, dict):
            # Recursively sort the nested dictionary
            sorted_dict = sort_dict_recursive(value)
            # Combine with the current result
            for k, v in sorted_dict.items():
                result[k] = v
    return result

def main():
    input_string = input("Enter a JSON object: ")
    json_obj = json.loads(input_string)
    sorted_dict = sort_dict_recursive(json_obj)
    print(sorted_dict)

if __name__ == "__main__":
