        char digitToCompare = '1'; // Example: find '1's
        int maxFrequency = 0;
        String maxNumber = null;

        for (String numeral : sortedPrimeNumerals) {
            int frequency = digitFrequency.getOrDefault((char) numeral.charAt(0), 0);
            if (frequency > maxFrequency) {
                maxFrequency = frequency;
                maxNumber = numeral;
