    private static List<String> computePrimeNumerals(int lower, int upper) {
        List<String> numerals = new ArrayList<>();
        for (int num = lower; num <= upper; num++) {
            if (isPrime(num)) {
                numerals.add(String.valueOf(num));
            }
        }
        return numerals;
    }

    // Check if a number is prime
    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        if (num == 2) return true;
        if (num % 2 == 0) return false;
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) return false;
        }
        return true;
    }

    // Sort numerals in ascending order
    private static List<String> sortNumerals(List<String> numerals) {
        List<String> sorted = new ArrayList<>(numerals);
        Collections.sort(sorted);
        return sorted;
    }

    // Compute frequency of each digit in the numerals
    private static Map<Character, Integer> computeDigitFrequency(List<String> numerals) {
        Map<Character, Integer> frequency = new HashMap<>();
        for (String numeral : numerals) {
            for (char digit : numeral.toCharArray()) {
                frequency.put(digit, frequency.getOrDefault(digit, 0) + 1);
            }
        }
        return frequency;
    }
