#include <iostream>
#include <string>
#include <map>
#include <sstream>
using namespace std;

map<string, int> wordLength(string str) {
    map<string, int> result;
    stringstream ss(str);
    string word;

    while (ss >> word) {
        // Skip one-letter words
        if (word.length() == 1) {
            continue;
        }
        // Add the word and its length to the map
        result[word] = word.length();
    }

