B = zeros(size(A, 1), size(A, 2)); % Initialize matrix B with the same number of rows as A and 2 columns.

% Loop through each row in A
for i = 1:size(A, 1)
    % Get the current timestamp and value
    current_timestamp = A(i, 1);
    current_value = A(i, 2);

    % Loop through the rest of the rows to find the next 16 hours difference
    for j = i+1:size(A, 1)
        % Get the next timestamp and value
        next_timestamp = A(j, 1);
        next_value = A(j, 2);

        % Calculate the difference between the current and next timestamp
        time_difference = next_timestamp - current_timestamp;

        % Check if the time difference is 16 hours
        if abs(time_difference) == 16 * 60 * 60 % 16 hours in seconds
            % Store the value in matrix B
            B(i, 2) = next_value;
            break; % Exit the inner loop since we found the next 16 hours value
        end
    end
end

% Display the result
