Here's a complete **C++ program** that:

1. Takes an array as input.
2. Checks if the array is already sorted in ascending order.
3. If not, it sorts the array using **Bubble Sort** (a basic sorting algorithm).
4. Outputs the result accordingly.

---

### ✅ C++ Program

```cpp
#include <iostream>
using namespace std;

// Function to check if the array is already sorted in ascending order
bool isArraySorted(int arr[], int size) {
    for (int i = 0; i < size - 1; ++i) {
        if (arr[i] > arr[i + 1]) {
            return false; // Not sorted
        }
    }
    return true; // Sorted
}

// Function to sort the array using Bubble Sort
void bubbleSort(int arr[], int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (arr[j] > arr[j + 1]) {
                // Swap arr[j] and arr[j + 1]
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

// Function to print the array
void printArray(int arr[], int size) {
    cout << "[";
    for (int i = 0; i < size; ++i) {
        cout << arr[i];
        if (i != size - 1) {
            cout << ", ";
        }
    }
    cout << "]" << endl;
}

int main() {
    const int MAX_SIZE = 100;
    int arr[MAX_SIZE];
    int size;

    // Input the size of the array
    cout << "Enter the number of elements (max 100): ";
    cin >> size;

    // Input the array elements
    cout << "Enter " << size << " elements:\n";
    for (int i = 0; i < size; ++i) {
        cin >> arr[i];
    }

    // Check if the array is already sorted
    if (isArraySorted(arr, size)) {
        cout << "Array is already sorted" << endl;
    } else {
        bubbleSort(arr, size);
        cout << "Sorted array: ";
        printArray(arr, size);
    }

    return 0;
}
```

