        if (arr[i] < arr[i - 1]) {
            return false;
        }
    }
    return true;
}

// Function to sort the array in ascending order
std::vector<int> sortArray(const std::vector<int>& arr) {
    if (arr.empty()) {
        return arr;
    }

    // Create a copy of the array
    std::vector<int> sortedCopy = arr;

    // Initialize a new array to hold the sorted elements
    std::vector<int> sorted;

    // Copy elements from the original array to the sorted array
    for (int num : arr) {
        sorted.push_back(num);
    }

    // Sort the copy in ascending order
    std::sort(sortedCopy.begin(), sortedCopy.end());

    // Return the sorted array
    return sortedCopy;
}

int main() {
    std::vector<int> input = {4, 2, 1, 7, 10};

    // Check if the input is already sorted
    if (isSorted(input)) {
        std::cout << "Array is already sorted.\n";
    } else {
        std::vector<int> sortedArray = sortArray(input);
        std::cout << "Sorted array: " << sortedArray[0] << ", " << sortedArray[1] << ", " << sortedArray[2] << ", " << sortedArray[3] << ", " << sortedArray[4] << "\n";
    }

    return 0;
}
